// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title NotificationRegistry
 * @dev Manages notification preferences and email dispatch requests
 *      for a role-based access control system. Off-chain relayer
 *      reads events and sends actual emails.
 */
contract NotificationRegistry {
    enum Role { NONE, USER, MODERATOR, ADMIN }

    struct UserProfile {
        address wallet;
        string displayName;
        string email;
        Role role;
        bool active;
    }

    mapping(address => UserProfile) public profiles;
    mapping(address => bool) public registeredRelayers;
    address public owner;

    event EmailDispatchRequested(
        address indexed recipient,
        string toEmail,
        string subject,
        string body,
        string replyTo
    );

    event ProfileUpdated(address indexed user, string displayName, string email);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyRole(Role _minRole) {
        require(profiles[msg.sender].role >= _minRole, "Insufficient role");
        require(profiles[msg.sender].active, "Account inactive");
        _;
    }

    modifier onlyRelayer() {
        require(registeredRelayers[msg.sender], "Not authorized relayer");
        _;
    }

    constructor() {
        owner = msg.sender;
        profiles[msg.sender] = UserProfile({
            wallet: msg.sender,
            displayName: "Admin",
            email: "admin@system.local",
            role: Role.ADMIN,
            active: true
        });
    }

    function registerRelayer(address _relayer) external onlyOwner {
        registeredRelayers[_relayer] = true;
    }

    function revokeRelayer(address _relayer) external onlyOwner {
        registeredRelayers[_relayer] = false;
    }

    function registerUser(string calldata _name, string calldata _email) external {
        require(profiles[msg.sender].role == Role.NONE, "Already registered");
        require(_validateEmailFormat(_email), "Invalid email format");
        profiles[msg.sender] = UserProfile({
            wallet: msg.sender,
            displayName: _name,
            email: _email,
            role: Role.USER,
            active: true
        });
        emit ProfileUpdated(msg.sender, _name, _email);
    }

    function updateProfile(string calldata _name, string calldata _email) external onlyRole(Role.USER) {
        require(_validateEmailFormat(_email), "Invalid email format");
        profiles[msg.sender].displayName = _name;
        profiles[msg.sender].email = _email;
        emit ProfileUpdated(msg.sender, _name, _email);
    }

    function promoteUser(address _user, Role _newRole) external onlyRole(Role.ADMIN) {
        require(_newRole != Role.NONE, "Cannot set NONE");
        profiles[_user].role = _newRole;
    }

    function deactivateUser(address _user) external onlyRole(Role.MODERATOR) {
        profiles[_user].active = false;
    }

    /**
     * @dev Sends a notification email to a target user. The subject is
     *      constructed from the sender's display name. Moderators+ can
     *      send to any user. The replyTo field uses the sender's stored email.
     */
    function sendNotification(
        address _to,
        string calldata _subject,
        string calldata _body
    ) external onlyRole(Role.MODERATOR) {
        require(profiles[_to].active, "Recipient inactive");
        string memory recipientEmail = profiles[_to].email;
        string memory senderName = profiles[msg.sender].displayName;

        // Build subject line: "[SystemNotify] <senderName>: <subject>"
        string memory fullSubject = string(abi.encodePacked(
            "[SystemNotify] ", senderName, ": ", _subject
        ));

        // replyTo is derived from sender's profile email
        string memory replyTo = profiles[msg.sender].email;

        emit EmailDispatchRequested(
            _to,
            recipientEmail,
            fullSubject,
            _body,
            replyTo
        );
    }

    /**
     * @dev Validates email format - checks for @ symbol and rejects
     *      newline characters to prevent header injection in the
     *      email field itself.
     */
    function _validateEmailFormat(string memory _email) internal pure returns (bool) {
        bytes memory emailBytes = bytes(_email);
        if (emailBytes.length == 0 || emailBytes.length > 254) return false;
        bool hasAt = false;
        for (uint i = 0; i < emailBytes.length; i++) {
            if (emailBytes[i] == 0x0a || emailBytes[i] == 0x0d) return false; // newline check
            if (emailBytes[i] == 0x40) hasAt = true; // @ symbol
        }
        return hasAt;
    }

    /**
     * @dev Admin can set arbitrary display name for operational purposes.
     *      Display names have relaxed validation since they're "display only".
     */
    function adminSetDisplayName(address _user, string calldata _name) external onlyRole(Role.ADMIN) {
        require(profiles[_user].role != Role.NONE, "User not registered");
        profiles[_user].displayName = _name;
    }

    function getProfile(address _user) external view returns (
        string memory displayName,
        string memory email,
        Role role,
        bool active
    ) {
        UserProfile storage p = profiles[_user];
        return (p.displayName, p.email, p.role, p.active);
    }
}
